from h import *

nueva('auricularia-auricula-judae', cient='Auricularia auricula-judae', sin=['Tremella auricula'], es=['oreja de Judas'], eu=['Judasen belarri', 'Judasen belarria'], grupo='gelatinosa', clase='sin_datos', cand=True,
  nota='Wikipedia: comestible pero de poco interés culinario. En el este de Asia se usa una especie parecida (A. heimuer), que a menudo se ha identificado mal como esta.',
  clave='Orejas gelatinosas pardo-rojizas, sin láminas, sobre madera de frondosas (sobre todo saúco). Elásticas y blandas con humedad, se secan duras y quebradizas.',
  mirar=[q('sombrero', 'Forma de oreja flácida', 'Hasta 9 cm de ancho y 3 mm de grosor; a veces en forma de copa. Se pega por un lado, a veces con un pie cortísimo. Fresca es dura, gelatinosa y elástica; seca, dura y quebradiza.'),
         q('cutis', 'Pardo rojizo con tinte púrpura', 'La cara de arriba es pardo-rojiza con un tinte púrpura, cubierta de pelitos grises finísimos. Lisa de joven, ondulada con pliegues después; más oscura con la edad.'),
         q('himenio', 'Cara inferior lisa y con «venas»', 'Gris-parda más clara, lisa, a veces con pliegues o «venas» que la hacen más parecida a una oreja. No tiene láminas.'),
         q('habitat', 'Sobre saúco y otras frondosas', 'Madera de frondosas y arbustos, sobre todo saúco (Sambucus nigra); también arce, haya, fresno y bonetero. Muy rara vez sobre coníferas. A veces salen formas blancas, sin pigmento.')],
  conf=[c(None, 'Auricularia heimuer', 'Especie de Asia oriental que se ha confundido con esta (Wikipedia).', 'baja')],
  hab=['frondosas', 'hayedo', 'madera', 'arbol_vivo'], habt='Madera de frondosas y arbustos, sobre todo saúco; también arce, haya, fresno… Prefiere ramas viejas, donde actúa como saprótrofa o parásita débil. Crece sola, en grupos o en mechones.',
  rec=dict(acc='cortar', txt='Corte limpio con navaja. Fresca es elástica; si se seca se pone dura y quebradiza, y se rehidrata con humedad.'),
  cur=['El nombre viene de una leyenda medieval: «auricula Judae», la oreja de Judas, alude a Judas Iscariote y al saúco, el árbol donde más se encuentra.',
       'Un autor la comparó con «comer una goma de borrar con huesos».',
       'Se dice que en Polonia se consume con frecuencia.',
       'Linneo la describió en 1753 como Tremella auricula.'],
  meses=[], mnota=None, wp=['auricularia-auricula-judae'], rioja=False)

nueva('sparassis-crispa', cient='Sparassis crispa', sin=['Clavaria crispa'], es=['seta coliflor', 'clavaria rizada', 'barba de cabra'], eu=['azalore belaki', 'azalore belakia'], grupo='coral', clase='sin_datos', cand=True,
  clave='Masa globosa, como una coliflor o un montón de lasañas onduladas, blanca-crema, en la base de pinos y otras coníferas. Solo joven y fresca; es muy difícil de limpiar.',
  mirar=[q('sombrero', 'Globo enredado', 'Hasta 24 cm de ancho; las más grandes pesan 14 kg o más. Los lóbulos son planos y ondulados, parecidos a pasta de lasaña, de blanco a amarillo crema. Duros y gomosos de jóvenes, blandos después.'),
         q('olor', 'Olor agradable, sabor suave', 'Olor agradable y sabor suave.'),
         q('esporada', 'Esporada crema', 'Crema.'),
         q('habitat', 'En la base de coníferas', 'Parásita en la base de los troncos de coníferas: pino sobre todo, también pícea, cedro, alerce… Produce una podredumbre parda.')],
  conf=[c(None, 'Sparassis brevipes', 'Especie europea menos conocida: tiene los pliegues menos rizados y zonados y no tiene fíbulas (un detalle microscópico).', 'baja')],
  hab=['pinar', 'coniferas', 'arbol_vivo'], habt='Bastante común en Gran Bretaña y en Europa templada (no en la zona boreal), de julio a noviembre. Crece en la base de coníferas.',
  rec=dict(acc='cortar', txt='Wikipedia: solo joven y fresca. Es difícil de limpiar (se recomiendan un cepillo de dientes y agua corriente) porque se meten larvas y agujas de pino en los huecos. Las ya guardadas pueden atraer larvas.'),
  esp='crema',
  cur=['Hay ejemplares que pesan más de 14 kg.',
       'Un libro de cocina francés da cuatro recetas con esta seta y dice que hay que escaldarla 2–3 minutos y cocinarla despacio.',
       'En la Wikipedia en euskera se destaca que hay que limpiar a fondo todos los pliegues y que sirve para croquetas.'],
  meses=[7, 8, 9, 10, 11], mnota='De julio a noviembre en Gran Bretaña y Europa templada.', wp=['sparassis-crispa'], rioja=False)

nueva('amanita-rubescens', cient='Amanita rubescens', sin=[], es=['amanita rojiza'], eu=['galdakao lanperna', 'kuleto ardotsu', 'galanperna gorria'], grupo='laminar', clase='sin_datos', cand=True,
  nota='Cruda es tóxica (proteína hemolítica) y solo se comería muy cocinada. Se confunde con la A. pantherina (tóxica) y con otras amanitas peligrosas: no es para principiantes.',
  clave='Amanita de sombrero pardo rojizo con verrugas cuya carne y láminas se ponen ROSA-rojizas al golpearlas, con anillo estriado por arriba. Si no enrojece y el anillo es liso: pantherina, tóxica.',
  mirar=[q('sombrero', 'Pardo rojizo con verrugas', '5–15 cm; convexo. Con pequeñas verrugas de blanco a color caoba, a veces con un velo ocre-amarillo que la lluvia lava. El borde es liso, sin estrías.'),
         q('himenio', 'Láminas blancas con manchas rojas', 'Blancas y libres; muestran manchas rojas cuando se dañan.'),
         q('carne', 'Se pone rosa al golpearla', 'Blanca, rosa al golpearla o al aire; es la pista principal. Cruda tiene sabor suave con un ligero regusto acre.'),
         q('pie', 'Blanco con tonos del sombrero', '5–15 cm; blanco con tintes del color del sombrero.'),
         q('anillo', 'Anillo estriado por arriba', 'La cara de arriba del anillo tiene estrías (A. pantherina no).'),
         q('esporada', 'Esporada blanca', 'Blanca.'),
         q('habitat', 'Frondosas y coníferas', 'Suelos pobres y bosques caducifolios y de coníferas; de junio a noviembre en el Reino Unido.')],
  conf=[c('amanita-pantherina-muscaria', 'Amanita pantherina (falsa rubescens)', 'Venenosa: su carne NO enrojece y su anillo no es estriado. La carne rosa al golpearla es la clave para separarlas.', 'alta'),
        c(None, 'Otras Amanitas', 'Hay varias especies relacionadas difíciles de distinguir; Wikipedia avisa de que se parece a algunas tóxicas.', 'alta')],
  hab=['frondosas', 'coniferas', 'mixto'], habt='Común en gran parte de Europa y Asia: suelos pobres, bosques de frondosas y de coníferas.',
  rec=dict(acc='extraer', txt='Como toda Amanita: sácala entera, con la base. Si dudas entre ésta y pantherina, déjalas.'),
  esp='blanca', sind='Cruda contiene una proteína hemolítica (destruye glóbulos rojos) que se destruye al cocinarla. David Pegler: en grandes cantidades cruda puede causar anemia grave si no se trata. Algunos libros la tratan como venenosa.', lat=None, grav=None,
  cur=['«Blusher» («la que se sonroja») es su nombre en inglés, por cómo enrojece la carne.',
       'En Sudáfrica llegó, al parecer, por accidente con árboles importados de Europa.',
       'Está tan extendida que se ve de junio a noviembre en el Reino Unido.'],
  meses=[6, 7, 8, 9, 10, 11], mnota='Reino Unido: de junio a noviembre.', wp=['amanita-rubescens'], rioja=False)

nueva('clitocybe-nebularis', cient='Clitocybe nebularis', sin=['Lepista nebularis', 'Agaricus nebularis'], es=[], eu=['ilarraka', 'pago-ziza', 'urriziza beltza'], grupo='laminar', clase='sin_datos', cand=True,
  nota='Wikipedia: comestible, pero incluso una pequeña ración da molestias digestivas a algunas personas. Se confunde con la Entoloma sinuatum tóxica.',
  clave='Seta grande gris con pie grueso, olor desagradable (a harina, especiado o rancio) y esporada amarillenta clara; sale en filas o corros en otoño. Su doble tóxico es la Entoloma sinuatum, de láminas rosadas.',
  mirar=[q('sombrero', 'Gris, con pruina blanca', '5–25 cm; convexo con el borde incurvado, luego plano o hundido. Gris a pardo-grisáceo claro, a menudo con una pruina blanquecina de joven y fibrillas en radios.'),
         q('himenio', 'Láminas pálidas, bifurcadas', 'Pálidas, de adnatas a algo decurrentes, apretadas y a menudo bifurcadas.'),
         q('pie', 'Grueso, abultado en la base', '5–10 cm de alto y 2–4 cm de ancho; grueso, hinchado hacia la base, hueco con la edad y se rompe con facilidad. Algo más claro que el sombrero.'),
         q('carne', 'Blanca, muy gruesa, huele mal', 'Blanca y muy gruesa. Olor desagradable: entre harinoso y especiado o rancio.'),
         q('esporada', 'Esporada amarillenta clara', 'Esporas amarillas; la huella es de un amarillo claro.'),
         q('habitat', 'Grupos en filas o corros', 'En otoño, sobre todo en octubre y noviembre (Wikipedia en euskera), en brezales y bosques de coníferas y de frondosas, donde se acumula mucho humus. Aparece a menudo en grupos, formando filas o círculos.')],
  conf=[c('entoloma-lividum-sinuatum', 'Entoloma sinuatum', 'Tóxica (puede aparecer en Europa y América del Norte). Tiene las láminas rosadas y sinuosas, no pálidas.', 'alta'),
        c(None, 'Otras setas grandes de carne blanca', 'También se parece a C. robusta (más blanca), C. irina (esporada rosada), Leucopaxillus albissimus, Tricholoma saponaceum e Infundibulicybe geotropa (de sombrero pardo claro).', 'media')],
  hab=['coniferas', 'frondosas', 'brezal'], habt='Muy abundante, en bosques con mucho humus: de coníferas y de frondosas, y también en brezales. En el Reino Unido aparece de mediados a finales de otoño.',
  rec=dict(acc='cortar', txt='Tamaño mínimo que recomienda La Rioja: 4 cm. Wikipedia avisa de que incluso una ración pequeña puede dar molestias digestivas a algunas personas: no la pruebes en cantidad. Cuidado con la Entoloma.'),
  esp='amarillenta clara', sind='Molestias gastrointestinales en algunas personas, incluso con poca cantidad.', lat=None, grav=None,
  cur=['«nebularis» viene del latín «nebula», niebla, por su color gris apagado.',
       'En 1953 químicos suecos aislaron de esta seta la nebularina.',
       'Es el anfitrión de otra seta parásita, Volvariella surrecta, que crece sobre los ejemplares viejos.',
       'La describió August Batsch en 1789 como Agaricus nebularis.'],
  meses=[9, 10, 11], mnota='Otoño; sobre todo octubre y noviembre.', wp=['clitocybe-nebularis'], rioja=True)
